480	// For tests: time moves only when advanced, and due timers run in order (by due time, then by the
481	// order they were set), each seeing now() equal to its own due time.
482	export class ManualClock implements Clock {
483	  #now: number;
484	  #nextId = 1;
485	  #pending: Pending[] = [];
486	
487	  constructor(start: number) {
488	    this.#now = start;
489	  }
490	
491	  now(): number {
492	    return this.#now;
493	  }
494	
495	  setTimeout(fn: () => void, ms: number): TimerHandle {
496	    const id = this.#nextId++;
497	    this.#pending.push({ id, due: this.#now + Math.max(0, ms), fn });
498	    return { id };
499	  }
500	
501	  clearTimeout(handle: TimerHandle): void {
502	    this.#pending = this.#pending.filter((p) => p.id !== handle.id);
503	  }
504	
505	  pending(): number {
506	    return this.#pending.length;
507	  }
508	
509	  advance(ms: number): void {
510	    if (ms < 0) throw new RangeError('a clock cannot go backwards');
511	    const target = this.#now + ms;
512	    for (let fired = 0; ; fired++) {
513	      if (fired > 1_000_000) throw new Error('runaway timers: over a million fired in one advance');
514	      const next = this.#nextDue(target);
515	      if (!next) break;
516	      this.#pending = this.#pending.filter((p) => p !== next);
517	      this.#now = next.due;
518	      next.fn();
519	    }
520	    this.#now = target;
521	  }
522	
523	  #nextDue(target: number): Pending | undefined {
524	    let best: Pending | undefined;
525	    for (const p of this.#pending) {
526	      if (p.due <= target && (!best || p.due < best.due || (p.due === best.due && p.id < best.id))) best = p;
527	    }
528	    return best;
529	  }
530	}
