33	// ---- ack matching: the one implementation (L2.33) ----
34	
35	export interface SendTime { atMs: number }
36	
37	// The send an ack belongs to: the latest send of its command_id at or before the moment the ack
38	// was received. -1 if no send precedes it. Never "the nth ack is for the nth send": acks are lost
39	// on the radio, and resending an id returns the original result (PROTOCOL.md §5).
40	export function matchAck(sends: readonly SendTime[], ackRxMs: number): number {
41	  let best = -1;
42	  for (let i = 0; i < sends.length; i++) {
43	    const s = sends[i]!;
44	    if (s.atMs <= ackRxMs && (best < 0 || s.atMs >= sends[best]!.atMs)) best = i;
45	  }
46	  return best;
47	}
48	
49	// Sends and acks by command_id, for the registry and for any tool that reads acks.
50	export class AckBook {
51	  readonly #sends = new Map<string, Array<{ atMs: number; acked: boolean }>>();
52	
53	  sent(commandId: string, atMs: number, acked = false): number {
54	    const list = this.#sends.get(commandId) ?? [];
55	    list.push({ atMs, acked });
56	    this.#sends.set(commandId, list);
57	    return list.length - 1;
58	  }
59	
60	  // Which send an ack is for, and whether that send already had one (a duplicate, L2.32). Null when
61	  // none of our sends of that id precedes it: someone else's command, or not ours at all.
62	  ack(commandId: string, rxMs: number): { sendIndex: number; duplicate: boolean } | null {
63	    const list = this.#sends.get(commandId);
64	    if (!list) return null;
65	    const i = matchAck(list, rxMs);
66	    if (i < 0) return null;
67	    const s = list[i]!;
68	    const duplicate = s.acked;
69	    s.acked = true;
70	    return { sendIndex: i, duplicate };
71	  }
72	
73	  has(commandId: string): boolean {
74	    return this.#sends.has(commandId);
75	  }
76	}
