681	  #ack(m: Record<string, unknown>): void {
682	    const cid = typeof m.command_id === 'string' ? m.command_id : null;
683	    if (cid === null) return;
684	    const loc = this.#byCommandId.get(cid);
685	    if (!loc) return; // another client's command: acks are broadcast to everyone
686	    const now = this.#clock.now();
687	    const match = this.#book.ack(cid, now);
688	    if (!match) return;
689	    const { rec, attempt } = loc;
690	    const status = m.status === 'ACCEPTED' ? 'ACCEPTED' : 'REJECTED';
691	    const str = (x: unknown) => (typeof x === 'string' ? x : null);
692	    const info: AckInfo = {
693	      status, reason: str(m.reason), holder: str(m.holder), leaseId: str(m.lease_id),
694	      serverMs: typeof m.server_time_ms === 'number' ? m.server_time_ms : null, rxMs: now, sendIndex: match.sendIndex,
695	    };
696	    this.#store.recordAck({ commandId: cid, recordId: rec.id, status, reason: info.reason, holder: info.holder, leaseId: info.leaseId, serverMs: info.serverMs, rxMs: now, sendIndex: match.sendIndex, duplicate: match.duplicate });
697	    if (match.duplicate) { attempt.duplicateAcks++; this.#save(rec); return; } // L2.32: no state change
698	    attempt.sends[match.sendIndex]!.ackRxMs = now;
699	    attempt.ack = info;
700	
701	    if (status === 'ACCEPTED' && rec.action === 'TAKE_CONTROL' && info.leaseId && rec.actor.kind === 'operator') {
702	      this.#setLease({ vehicleId: rec.vehicleId, operatorId: rec.actor.operatorId, leaseId: info.leaseId, sinceServerMs: this.#fleet.serverNow() });
703	    }
704	    const current = attempt === rec.attempts.at(-1);
705	    if (rec.status === 'confirmed' && status === 'ACCEPTED' && rec.effect && !rec.effect.ackReceived) {
706	      rec.effect.ackReceived = true; // the ack came after the effect (L2.30): no longer "no ack received"
707	    }
708	    if (!OPEN_STATUSES.has(rec.status) || !current) {
709	      this.#save(rec, 'ack', `${status}${info.reason ? ` ${info.reason}` : ''} for ${cid} after the command was ${current ? rec.status : 'sent again'}`, undefined, cid);
710	      return;
711	    }
712	    if (status === 'ACCEPTED') {
713	      if (rec.status === 'sent') rec.status = 'acknowledged';
714	      this.#save(rec, 'ack', `${rec.action} ${rec.vehicleId} accepted by the site (not yet carried out)`, undefined, cid);
715	      if (rec.action === 'RESUME') this.#cancelQueuedBy(rec);
716	      this.#evaluate(rec.vehicleId); // the effect may already be in (L2.30)
717	      return;
718	    }
719	    this.#rejected(rec, attempt, info);
720	  }
