828	  #restore(): void {
829	    const now = this.#clock.now();
830	    for (const rec of this.#store.openCommands()) {
831	      this.#records.set(rec.id, rec);
832	      for (const a of rec.attempts) {
833	        this.#byCommandId.set(a.commandId, { rec, attempt: a });
834	        for (const s of a.sends) this.#book.sent(a.commandId, s.atMs, s.ackRxMs !== null);
835	      }
