923	// One line for the operator: what is happening to this command now.
924	export function summarise(r: CommandRecord, nowMs: number): string {
925	  const n = r.attempts.length;
926	  const attempt = n > 1 ? ` (attempt ${n} of ${r.maxAttempts})` : '';
927	  switch (r.status) {
928	    case 'pending':
929	      if (r.hold?.needsReconfirm) return 'NOT sent: the site link was down too long. Check the truck, then confirm again or cancel';
930	      if (r.hold) return `NOT sent yet: waiting for the site link (sends by itself for ${secs(Math.max(0, r.hold.autoSendUntilMs - nowMs))} more)`;
931	      return 'about to send';
932	    case 'sent':
933	      if (r.queued) return `sent, queued behind ${r.queued.behind}${attempt}`;
934	      return `sent, no answer from the site yet${attempt}`;
935	    case 'acknowledged':
