143	
144	const HEADER_H = 64;
145	const CHIP_LANE_H = 46;
146	const CHIP_H = 38;
147	const RANGE_LANE_H = 36;
148	const LINE_GAP = 22;
149	const chipX = new Map<string, number>();
150	
151	function defs(): SVGElement {
152	  const hatch = (id: string, color: string, cross: boolean) => svg('pattern', { id, width: 8, height: 8, patternUnits: 'userSpaceOnUse', patternTransform: 'rotate(45)' },
153	    svg('rect', { width: 8, height: 8, fill: '#0e1114' }),
154	    svg('line', { x1: 0, y1: 0, x2: 0, y2: 8, stroke: color, 'stroke-width': 3 }),
155	    ...(cross ? [svg('line', { x1: 0, y1: 4, x2: 8, y2: 4, stroke: color, 'stroke-width': 2 })] : []));
156	  return svg('defs', {},
157	    hatch('silent-hatch', '#9aa1a8', false),
158	    hatch('frozen-hatch', '#b06cbd', true),
159	    hatch('closed-hatch', '#6a2a24', false),
160	    svg('pattern', { id: 'unknown-dots', width: 6, height: 6, patternUnits: 'userSpaceOnUse' },
161	      svg('rect', { width: 6, height: 6, fill: '#14181c' }), svg('circle', { cx: 3, cy: 3, r: 1, fill: '#4a535c' })));
162	}
