164	function renderTrack(site: SiteData, snap: FleetSnapshot): void {
165	  const host = $('track');
166	  const width = Math.max(600, host.clientWidth);
167	  const m: TrackModel = trackModel(site, snap, width);
168	  const chipTop = HEADER_H;
169	  const lineY = chipTop + Math.max(1, m.chipLanes) * CHIP_LANE_H + LINE_GAP / 2;
170	  const rangeTop = lineY + LINE_GAP;
171	  const height = rangeTop + Math.max(1, m.rangeLanes) * RANGE_LANE_H + 8;
172	
173	  const root = svg('svg', { viewBox: `0 0 ${width} ${height}`, height, role: 'img', 'aria-label': 'Track diagram' }, defs());
174	  m.bands.forEach((b, i) => {
175	    const g = svg('g', { class: `band ${b.kind}${i % 2 ? ' alt' : ''}`, 'data-zone': b.zoneId ?? '' },
176	      svg('rect', { class: 'bg', x: b.x0, y: 0, width: b.x1 - b.x0, height }),
177	      svg('rect', { class: 'edge', x: b.x0 + 1, y: 1, width: Math.max(0, b.x1 - b.x0 - 2), height: height - 2 }),
178	      svg('text', { x: b.x0 + 8, y: 18 }, b.zoneId ?? '(gap in route)'),
179	      svg('text', { class: 'status', x: b.x0 + 8, y: 37 }, b.word),
180	      svg('text', { class: 'status', x: b.x0 + 8, y: 55 }, b.detail));
181	    root.append(g);
182	  });
183	  root.append(svg('line', { class: 'trackline', x1: 3, y1: lineY, x2: width - 3, y2: lineY }));
184	  root.append(svg('text', { class: 'ends', x: 4, y: lineY + 17 }, '↻ joins the right end'));
185	  root.append(svg('text', { class: 'ends', x: width - 4, y: lineY + 17, 'text-anchor': 'end' }, 'joins the left end ↻'));
186	
187	  for (const r of m.ranges) {
188	    const y = rangeTop + r.lane * RANGE_LANE_H;
189	    const g = svg('g', { class: `range ${r.kind}`, 'data-trucks': r.vehicleIds.join(' '), 'data-kind': r.kind });
190	    g.append(svg('text', { x: r.labelX, y: y + 12 }, r.label));
191	    for (const p of r.pieces) {
192	      g.append(svg('rect', { class: 'bar', x: p.x0, y: y + 17, width: Math.max(2, p.x1 - p.x0), height: 13 }));
193	      if (p.wrapsOut) g.append(svg('path', { class: 'wrap', d: `M${p.x1 - 2},${y + 15} l6,8 l-6,8` }));
194	      if (p.wrapsIn) g.append(svg('path', { class: 'wrap', d: `M${p.x0 + 2},${y + 15} l-6,8 l6,8` }));
195	    }
196	    if (r.anchorX !== null) g.append(svg('circle', { class: 'anchor', cx: r.anchorX, cy: y + 23.5, r: 5 }, svg('title', {}, 'last believable position')));
197	    root.append(g);
198	  }
199	
200	  // Higher lanes first, so a chip near the line is drawn over the connectors of chips stacked above it.
201	  const seen = new Set<string>();
202	  for (const c of [...m.chips].sort((a, b) => b.lane - a.lane)) {
203	    seen.add(c.vehicleId);
204	    const y = lineY - LINE_GAP / 2 - (c.lane + 1) * CHIP_LANE_H + (CHIP_LANE_H - CHIP_H);
205	    const prev = chipX.get(c.vehicleId);
206	    const jump = prev !== undefined && Math.abs(prev - c.boxX) > width / 2; // wrapped round the loop
207	    chipX.set(c.vehicleId, c.boxX);
208	    const g = svg('g', { class: `chip ${c.kind}${c.fault ? ' fault' : ''}${jump ? ' jump' : ''}`, 'data-truck': c.vehicleId, 'data-kind': c.kind, style: `transform: translate(${c.boxX}px, 0px)` },
209	      svg('line', { x1: 0, y1: y + CHIP_H, x2: c.x - c.boxX, y2: lineY }),
210	      svg('rect', { x: -c.width / 2, y, width: c.width, height: CHIP_H }),
211	      svg('text', { x: 0, y: y + (c.lines.length > 1 ? 16 : 24) }, c.lines[0]!),
212	      ...(c.lines[1] ? [svg('text', { class: 'badge', x: 0, y: y + 31 }, c.lines[1])] : []));
213	    root.append(g);
214	  }
215	  for (const id of [...chipX.keys()]) if (!seen.has(id)) chipX.delete(id);
216	
217	  // Chips keep their element between frames so they glide; everything else is redrawn.
218	  const old = host.querySelector('svg');
219	  if (old) {
220	    for (const g of root.querySelectorAll<SVGGElement>('g.chip')) {
221	      const before = old.querySelector<SVGGElement>(`g.chip[data-truck="${g.dataset.truck}"]`);
222	      if (before && !g.classList.contains('jump')) {
223	        before.setAttribute('class', g.getAttribute('class')!);
224	        before.replaceChildren(...g.childNodes);
225	        before.style.transform = g.style.transform;
226	        g.replaceWith(before);
227	      }
228	    }
229	  }
230	  host.replaceChildren(root);
231	}
