281	let frozenOrder: string[] | null = null;
282	const FROZEN_CELL_PADDING = 15; // a cell's vertical padding and border (overview.css: td padding 7px)
283	
284	function setupRowFreeze(): void {
285	  const table = $('rows').closest('table')!;
286	  const body = $('rows');
287	  const freeze = () => {
288	    if (frozenOrder) return;
289	    const trs = [...body.querySelectorAll<HTMLElement>(':scope > tr')];
290	    frozenOrder = trs.map((tr) => tr.dataset.truck!);
291	    for (const tr of trs) {
292	      const h = tr.getBoundingClientRect().height;
293	      tr.style.height = `${h}px`;
294	      tr.style.setProperty('--h', `${Math.max(0, h - FROZEN_CELL_PADDING)}px`);
295	    }
296	    body.classList.add('frozen');
297	    $('order-paused').hidden = false;
298	  };
299	  const thaw = () => {
300	    if (table.matches(':hover') || table.contains(document.activeElement)) return;
301	    frozenOrder = null;
302	    body.classList.remove('frozen');
303	    for (const tr of body.querySelectorAll<HTMLElement>(':scope > tr')) { tr.style.removeProperty('height'); tr.style.removeProperty('--h'); tr.classList.remove('clipped'); }
304	    if (frame) renderRows(frame.snapshot);
305	  };
306	  table.addEventListener('pointerenter', freeze);
307	  table.addEventListener('pointerleave', () => clock.setTimeout(thaw, 0));
308	  table.addEventListener('focusin', freeze);
309	  table.addEventListener('focusout', () => clock.setTimeout(thaw, 0));
310	}
