316	    td({ class: 'data' }, r.data, r.restarted ? el('span', { class: 'restart', title: 'Controller restarted: its data is being used again; no action needed' }, `↻ ${r.restarted}`) : null),
317	    td({ class: 'why' }, r.attention ?? ''),
