377	
378	// Browsers block sound until the page is clicked, so "Sound off" shows until the operator arms it
379	// (UI.md). Interrupts only, a short tone pattern each, never continuous.
380	let audio: AudioContext | null = null;
381	const heard = new Map<string, number>(); // alertSeq heard per alarm key on this screen
382	let missed = 0;                          // interrupts that alerted while sound was off
383	
384	function setupSound(): void {
385	  const b = $('sound');
386	  b.addEventListener('click', () => {
387	    const Ctx = (window as unknown as { AudioContext?: typeof AudioContext }).AudioContext;
388	    if (!Ctx) { b.textContent = 'Sound unavailable in this browser'; return; }
389	    const ctx = audio ?? new Ctx();
390	    void ctx.resume().then(() => {
391	      audio = ctx;
392	      missed = 0;
393	      b.dataset.armed = 'true';
394	      b.dataset.missed = 'false';
395	      b.textContent = 'Sound armed';
396	      play([{ hz: 660, ms: 80 }]); // a quiet click of confirmation
397	    });
398	  });
399	}
400	
401	function play(pattern: Array<{ hz: number; ms: number }>): void {
402	  if (!audio || audio.state !== 'running') return;
403	  let t = audio.currentTime + 0.02;
404	  for (const n of pattern) {
405	    const osc = audio.createOscillator();
406	    const gain = audio.createGain();
407	    osc.frequency.value = n.hz;
408	    gain.gain.setValueAtTime(0.0001, t);
409	    gain.gain.exponentialRampToValueAtTime(0.25, t + 0.015);
410	    gain.gain.exponentialRampToValueAtTime(0.0001, t + n.ms / 1000);
411	    osc.connect(gain).connect(audio.destination);
412	    osc.start(t);
413	    osc.stop(t + n.ms / 1000 + 0.02);
414	    t += n.ms / 1000 + 0.06;
415	  }
416	}
