418	// One pattern per frame at most, the most urgent first: several alarms at once are still one short
419	// sound, never a run of them.
420	function soundFor(items: AlarmItem[]): void {
421	  const due = toSound(items, you?.id ?? null, heard);
422	  if (due.length === 0) return;
423	  document.body.dataset.alerted = String(Number(document.body.dataset.alerted ?? '0') + due.length); // for tests
424	  const first = due.find((i) => i.source === 'blast') ?? due.find((i) => i.source === 'link') ?? due[0]!;
425	  if (audio && audio.state === 'running') { play(tonePattern(first)); return; }
426	  missed += due.length;
427	  const b = $('sound');
428	  b.dataset.missed = 'true';
429	  b.textContent = `Sound off: ${missed} alarm${missed > 1 ? 's' : ''} not heard. Click to arm`;
430	}
