434	function connectLive(): void {
435	  const ws = new WebSocket(`${location.protocol === 'https:' ? 'wss' : 'ws'}://${location.host}/api/live`);
436	  ws.onopen = () => { socket = ws; };
437	  ws.onmessage = (e) => {
438	    let m: { type?: string; [k: string]: unknown };
439	    try { m = JSON.parse(String(e.data)); } catch { return; }
440	    if (m.type === 'frame') {
441	      const body = m.body as { frame: Frame };
442	      frame = body.frame;
443	      you = m.you as You;
444	      notices = (m.notices as Notice[]) ?? [];
445	      detail = (m.detail as TruckDetail | null) ?? null;
446	      lastFrameAt = clock.now();
447	      if (openTruck && $('detail').hidden) openDetail(openTruck); // opened from the address (#truck=...)
448	      render();
449	    } else if (m.type === 'result') {
450	      onResult(m as unknown as Result);
451	    }
452	  };
453	  ws.onclose = (e) => {
454	    if (socket === ws) socket = null;
455	    renderLinks();
456	    if (e.code === 4401) { location.href = '/login'; return; } // the session ended
457	    clock.setTimeout(() => void reconnect(), RECONNECT_MS);
458	  };
459	}
