470	interface Result { type: 'result'; ref: string | null; ok: boolean; error?: string; command?: CommandView; history?: { lines: AuditLine[]; truncated: boolean; atServerMs: number } }
471	const asked = new Map<string, string>(); // ref -> truck, for e-stops sent and not yet answered
472	let refN = 0;
473	
474	const handlers = new Map<string, (m: Result) => void>(); // ref -> what to do with its result
475	
476	function onResult(m: Result): void {
477	  const h = m.ref ? handlers.get(m.ref) : undefined;
478	  if (h) { handlers.delete(m.ref!); h(m); return; }
479	  const truck = m.ref ? asked.get(m.ref) : undefined;
480	  if (m.ref) asked.delete(m.ref);
481	  if (!m.ok && truck) estopNote(`E-stop ${truck} NOT sent: ${m.error ?? m.command?.summary ?? 'refused'}`, true);
482	  else if (truck) estopNote(`E-stop ${truck}: ${m.command?.summary ?? 'sent'}`, false);
483	  else if (!m.ok) estopNote(m.error ?? m.command?.summary ?? 'refused', true);
484	  renderEstops();
485	}
