500	function estop(truck: string): void {
501	  const ref = send({ type: 'command', action: 'ESTOP', vehicleId: truck });
502	  if (ref === null) {
503	    // Never queued: a stop sent later, unseen, is a different decision (L7.8).
504	    estopNote(`E-stop ${truck} NOT sent: the service is disconnected. Use the radio.`, true);
505	    return;
506	  }
507	  asked.set(ref, truck);
508	  estopNote(`E-stop ${truck}: sending…`, false);
