511	// The e-stop state of one truck, in a word: our open command first, then the truck's own report.
512	// "stopped" only when the truck itself says ESTOPPED.
513	function estopWord(truck: string, live: LiveState, snap: FleetSnapshot): { word: string; kind: string } {
514	  const t = snap.trucks.find((x) => x.vehicleId === truck);
515	  const c = live.commands.find((x) => x.vehicleId === truck && x.action === 'ESTOP');
516	  if (c?.needsReconfirm) return { word: 'NOT sent', kind: 'reconfirm' };
517	  if (c?.waitingForLink) return { word: 'pending', kind: 'pending' };
518	  if (c && c.open) return { word: 'sent', kind: 'sent' };
519	  if (c && (c.status === 'failed' || c.status === 'expired')) return { word: 'NOT done', kind: 'failed' };
520	  if (t?.state?.value === 'ESTOPPED') return { word: 'stopped', kind: 'stopped' };
521	  return { word: 'STOP', kind: 'ready' };
522	}
