524	function renderEstops(): void {
525	  const live = frame?.live;
526	  const snap = frame?.snapshot;
527	  const box = $('estop-trucks');
528	  if (!live || !snap) return;
529	  const ids = snap.trucks.filter((t) => t.onRoster !== false).map((t) => t.vehicleId);
530	  // Buttons keep their element between frames, so a press is never lost to a redraw.
531	  const have = new Map([...box.querySelectorAll<HTMLButtonElement>('button')].map((b) => [b.dataset.truck!, b]));
532	  const buttons = ids.map((id) => {
533	    let b = have.get(id);
534	    if (!b) {
535	      b = el('button', { type: 'button', class: 'estop-truck', 'data-truck': id }, el('b', {}, id), el('span', {}, 'STOP'));
536	      b.addEventListener('click', () => estop(id));
537	    }
538	    const s = estopWord(id, live, snap);
539	    b.dataset.kind = s.kind;
