    const vehicle = typeof m.vehicle_id === 'string' ? m.vehicle_id : null;
    const action = String(m.action);
    const id = m.command_id;
    if (typeof id !== 'string' || id.length === 0 || id.length > MAX_COMMAND_ID) {
