export type DialMode = 'normal' | 'outage' | 'blackhole';

export class FakeDialer {
  mode: DialMode = 'normal';
  readonly dialTimes: number[] = [];
  readonly sentLines: string[] = [];
  readonly #gw: FakeGateway;
  readonly #clock: ManualClock;
  readonly #open = new Set<{ conn: Connection; close(): void }>();

  constructor(gw: FakeGateway, clock: ManualClock) {
    this.#gw = gw;
    this.#clock = clock;
  }

  get dials(): number { return this.dialTimes.length; }
  get openConnections(): number { return this.#open.size; }

  dial: Dialer = (h) => {
    this.dialTimes.push(this.#clock.now());
    if (this.mode === 'outage') {
      let closed = false;
      return {
        write: (line) => { this.sentLines.push(line); if (!closed) { closed = true; h.onClose('closed by the gateway'); } },
        close: () => { closed = true; },
      };
    }
    let closed = false;
    const conn = this.#gw.attach({
      write: (line) => { if (!closed && this.mode !== 'blackhole') h.onLine(line); },
      close: () => { if (!closed) { closed = true; this.#open.delete(entry); h.onClose('connection closed by the gateway'); } },
    });
    const entry = { conn, close: () => { closed = true; this.#open.delete(entry); conn.disconnect(); } };
    this.#open.add(entry);
    return {
      write: (line) => { this.sentLines.push(line); if (!closed) conn.receive(line); },
      close: () => entry.close(),
    };
  };

  // The gateway drops everyone.
  dropAll(): void {
    for (const e of [...this.#open]) this.#gw.drop(e.conn, true);
  }
}

export interface LinkRig {
  clock: ManualClock;
  gw: FakeGateway;
  dialer: FakeDialer;
  fleet: FleetState;
  store: Store;
  registry: CommandRegistry;
  link: GatewayLink;
  linkEvents: LinkEvent[];
  events: RegistryEvent[];
  dbPath: string;
  advance(ms: number, stepMs?: number): void;
  until(pred: () => boolean, maxMs: number, stepMs?: number): number; // elapsed ms, or -1
  restartService(): LinkRig; // a new process on the same database, the same gateway and clock
  cleanup(): void;
}

export function linkRig(config: Partial<FakeConfig> = {}, o: { gate?: SafetyGate; random?: () => number; email?: string; shared?: { clock: ManualClock; gw: FakeGateway; dialer: FakeDialer; dbPath: string } } = {}): LinkRig {
  const tmp = o.shared ? null : tempDir();
  const clock = o.shared?.clock ?? new ManualClock(T0);
  const gw = o.shared?.gw ?? new FakeGateway(clock, { seed: 7, site: DLH1, blasts: 'none', ...config });
  if (!o.shared) gw.start();
  const dialer = o.shared?.dialer ?? new FakeDialer(gw, clock);
  const dbPath = o.shared?.dbPath ?? tmp!.dbPath;
  const fleet = new FleetState(clock);
  const store = new Store(dbPath);
  const link = new GatewayLink({ clock, fleet, dial: dialer.dial, email: o.email ?? '<redacted-email>', random: o.random ?? (() => 0.5) });
  let n = 0;
  const registry = new CommandRegistry({ clock, fleet, store, transport: link, gate: o.gate ?? ALLOW_ALL_GATE_NO_BLAST_SAFETY, newId: () => `r${clock.now() - T0}-${++n}-${Math.floor(clock.now() % 997)}` });
  attachRegistry(link, registry);
  const linkEvents: LinkEvent[] = [];
  const events: RegistryEvent[] = [];
  link.subscribe((e) => linkEvents.push(e));
  registry.subscribe((e) => events.push(e));
  fleet.start();
  registry.start();
  const rig: LinkRig = {
    clock, gw, dialer, fleet, store, registry, link, linkEvents, events, dbPath,
    advance(ms, stepMs = 50) {
      for (let left = ms; left > 0; left -= stepMs) clock.advance(Math.min(stepMs, left));
    },
    until(pred, maxMs, stepMs = 50) {
      const start = clock.now();
      while (clock.now() - start <= maxMs) {
        if (pred()) return clock.now() - start;
        clock.advance(stepMs);
      }
      return -1;
    },
    restartService() {
      link.stop();
      registry.stop();
      fleet.stop();
      store.close();
      return linkRig(config, { ...o, shared: { clock, gw, dialer, dbPath } });

  snapshot(): FleetSnapshot {
    const now = this.#clock.now();
    const site = this.#site;
    const fleet = this.#fleetDrain();
    const trucks = this.#orderedTrucks().map((t) => this.#view(t, now, fleet));
    const zoneIds = [...(site?.zones.map((z) => z.zoneId) ?? []), ...[...this.#zones.keys()].filter((id) => !site?.zone(id))];
    const zones = [...new Set(zoneIds)].map((id): ZoneView => {
      const z = this.#zones.get(id);
      const eff = z?.effectiveAtMs ?? null;
      return {
        zoneId: id,
        status: z?.status ?? null,
        reason: z?.reason ?? null,
        effectiveAtMs: eff,
        msUntilEffective: eff === null ? null : eff - this.serverNow(),
        updatedServerMs: z?.updatedServerMs ?? null,
        trucksMightBeIn: trucks.filter((t) => t.range === null || t.mightBeIn.includes(id)).map((t) => t.vehicleId),
      };
    });
    const hb = this.#lastHeartbeat;
    const hbAge = hb ? now - hb.atLocal : null;
    const link = this.#link;
    return {
      atServerMs: this.serverNow(),
      link: { up: link?.up ?? null, sinceServerMs: link ? link.sinceLocal + this.#offset() : null, reason: link?.reason ?? 'not connected yet' },
      siteId: site?.siteId ?? null,
      loopLengthM: site?.loopLengthM ?? null,
      heartbeat: { lastServerMs: hb?.serverMs ?? null, ageMs: hbAge, stale: hbAge === null || hbAge >= PARAMS.linkDownAfter.value },
      zones,
      trucks,
      fleetDrain: { emptyPctPerKm: perKm(fleet.emptyPctPerM), loadedPctPerKm: perKm(fleet.loadedPctPerM) },
      dataQuality: { total: { ...this.#dqTotal }, connection: { ...this.#dqConnection } },
    };
  }

  // ---- dispatch ----

  #dispatch(m: Record<string, unknown> & { type: string }): void {
    const st = serverTimeOf(m);
    if (st !== undefined) this.#sample(st);
    switch (m.type) {
      case 'telemetry': this.#telemetry(m); break;
      case 'heartbeat':
        if (st === undefined) this.#linkDq('bad_message', 'heartbeat without server_time_ms');
        else this.#lastHeartbeat = { serverMs: st, atLocal: this.#clock.now() };
        break;
      case 'hello': this.#hello(m as unknown as Hello); break;
      case 'zone_event': this.#zoneEvent(m, st); break;
      // Commands, leases and drive refusals belong to the command registry and the gateway link;
      // here they only contribute server time.
      case 'command_ack': case 'lease_event': case 'drive_rejected': case 'auth_error': break;
      default: this.#linkDq('unknown_type', m.type);
    }
  }

  #hello(h: Hello): void {
    let built: { site: Site; issues: string[] };
    try {
      built = buildSite(h);
    } catch (e) {
      this.#linkDq('hello:invalid', e instanceof SiteError ? e.message : String(e));
      return;
    }
    const routeKey = JSON.stringify([h.loop_length_m, h.route]);
    if (this.#site && routeKey !== this.#routeKey) {
      // A different route: positions recorded against the old one mean nothing now.
      for (const t of this.#trucks.values()) { delete t.position; t.still = null; t.drainPrev = null; }
    }
    this.#site = built.site;
    this.#routeKey = routeKey;
    for (const i of built.issues) this.#linkDq('hello:route_issue', i);
    this.#emit({ type: 'site', siteId: built.site.siteId, issues: built.issues, atServerMs: this.serverNow() });

    this.#roster = Array.isArray(h.vehicles) ? h.vehicles.filter((v): v is string => typeof v === 'string') : [];
    for (const id of this.#roster) if (!this.#trucks.has(id)) this.#trucks.set(id, new Truck(id));
    for (const t of this.#trucks.values()) t.onRoster = this.#roster.includes(t.vehicleId);

    // The snapshot replaces what we knew. A route zone missing from it is unknown, not open.
    const at = serverTimeOf(h as unknown as Record<string, unknown>) ?? this.serverNow();
    const listed = new Set<string>();
    for (const raw of Array.isArray(h.zones) ? h.zones : []) {
      const { zone, issues } = validateZone(raw);
      for (const i of issues) this.#linkDq(i, JSON.stringify(raw));
      if (!zone) continue;
      listed.add(zone.zoneId);
      this.#setZone({ ...zone, updatedServerMs: at });
    }
    for (const z of built.site.zones) {
      if (!listed.has(z.zoneId)) this.#setZone({ zoneId: z.zoneId, status: null, reason: null, effectiveAtMs: null, updatedServerMs: at });
    }
    this.tick();
  }

  #zoneEvent(m: Record<string, unknown>, st: number | undefined): void {
    const { zone, issues } = validateZone(m);
    for (const i of issues) this.#linkDq(i, JSON.stringify(m));
    if (!zone) return;
    const prev = this.#zones.get(zone.zoneId);
    if (st !== undefined && prev?.updatedServerMs != null && st < prev.updatedServerMs) {
      this.#linkDq('zone_event:stale', `${zone.zoneId} ${zone.status} at ${st}, after ${prev.updatedServerMs}`);
      return;
    }
    this.#setZone({ ...zone, updatedServerMs: st ?? this.serverNow() });
  }

  #setZone(z: ZoneRecord): void {
    const prev = this.#zones.get(z.zoneId);
    this.#zones.set(z.zoneId, z);
    if (!prev || prev.status !== z.status || prev.effectiveAtMs !== z.effectiveAtMs || prev.reason !== z.reason) {
      this.#emit({ type: 'zone', zoneId: z.zoneId, status: z.status, reason: z.reason, effectiveAtMs: z.effectiveAtMs, atServerMs: this.serverNow() });
    }
  }

// Plain-words formatting shared by the clearance rule and the UI. Pure: no clock, no DOM.
import type { TruckView } from './fleet.ts';

// Whole seconds, counted down from the true age so "old 2 s" never claims more freshness than it has
// lost: 2.9 s is "2 s", and the next second shows when it is reached. Minutes past 90 s.
export function age(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000));
  if (s < 90) return `${s} s`;
  const m = Math.floor(s / 60);
  if (m < 90) return `${m} min ${s % 60} s`;
  return `${Math.floor(m / 60)} h ${m % 60} min`;
}

// A countdown as m:ss. Rounded up: "0:01" until the moment itself, never "0:00" early.
export function countdown(ms: number): string {
  const s = Math.max(0, Math.ceil(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

// Time since something, as m:ss. Rounded down, like age: "closed 0:03 ago" at 3.9 s.
export function elapsed(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

// How old the truck's position is: since the last valid position, or since the last message if it
// never sent one.
export function positionAgeMs(t: TruckView): number | null {
  return t.position?.ageMs ?? t.ageMs;
}

// The data state in words, as the fleet table shows it (UI.md: "live, old 4 s, silent 32 s,
// contradicted").
export function dataState(t: TruckView): string {
  const a = positionAgeMs(t);
  switch (t.confidence) {
    case 'live': return 'live';
    case 'old': return `old ${age(a ?? 0)}`;
    case 'silent': return `silent ${age(a ?? 0)}`;
    case 'contradicted': return 'contradicted';
    case 'unknown': return t.ageMs === null ? 'never reported' : 'no position';
  }
}

export function faultWords(t: TruckView): string | null {
  const f = t.faults?.value ?? [];
  return f.length ? `faulted (${f.join(', ')})` : null;
}

